INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '人口密度と面積から人口を求める', '以下の表は、ある地域の面積と人口密度を表したものである。最も人口が多いのはA〜Eのうちどれか。', '[{"headers":["地域","面積（km²）","人口密度（人/km²）"],"rows":[["A","55","820"],["B","62","710"],["C","48","905"],["D","70","640"],["E","39","880"]]}]', '["A","B","C","D","E"]', 0, '["人口＝面積×人口密度で概算します。","A：55×820＝45,100人／B：62×710＝44,020人／C：48×905＝43,440人／D：70×640＝44,800人／E：39×880＝34,320人","コツ：面積・密度ともに極端に小さいE、面積が最も小さいCはまず除外できます。残るA・B・Dを計算すると、Aが最多です。","よって、正解は1（A）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '人口密度と面積から人口を求める', '以下の表は、ある地域の面積と人口密度を表したものである。最も人口が少ないのはF〜Jのうちどれか。', '[{"headers":["地域","面積（km²）","人口密度（人/km²）"],"rows":[["F","44","530"],["G","61","390"],["H","35","610"],["I","50","470"],["J","58","405"]]}]', '["F","G","H","I","J"]', 2, '["F：44×530＝23,320人／G：61×390＝23,790人／H：35×610＝21,350人／I：50×470＝23,500人／J：58×405＝23,490人","コツ：面積が最も小さいHは、密度がやや高くても人口が少なくなりやすい候補です。実際に計算すると、Hが最少です。","よって、正解は3（H）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '人口密度と面積から人口を求める', '以下の表は、ある地域の面積と人口密度を表したものである。人口が2番目に多いのはK〜Oのうちどれか。', '[{"headers":["地域","面積（km²）","人口密度（人/km²）"],"rows":[["K","66","540"],["L","58","610"],["M","73","470"],["N","49","700"],["O","81","410"]]}]', '["K","L","M","N","O"]', 1, '["K：66×540＝35,640人／L：58×610＝35,380人／M：73×470＝34,310人／N：49×700＝34,300人／O：81×410＝33,210人","順に、K＞L＞M＞N＞O となります（MとNは僅差なので注意）。2番目に多いのはLです。","よって、正解は2（L）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '人口密度と面積から人口を求める', '以下の表は、ある地域の人口と人口密度を表したものである。面積が最も大きいのはP〜Tのうちどれか。', '[{"headers":["地域","人口（人）","人口密度（人/km²）"],"rows":[["P","52,000","520"],["Q","61,200","680"],["R","43,200","480"],["S","39,600","396"],["T","58,000","500"]]}]', '["P","Q","R","S","T"]', 4, '["面積＝人口÷人口密度で求めます。","P：52,000÷520＝100km²／Q：61,200÷680＝90km²／R：43,200÷480＝90km²／S：39,600÷396＝100km²／T：58,000÷500＝116km²","最も面積が大きいのはTです。","よって、正解は5（T）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '人口密度と面積から人口を求める', '以下の表は、ある地域の人口と面積を表したものである。人口密度が最も高いのはU〜Yのうちどれか。', '[{"headers":["地域","人口（人）","面積（km²）"],"rows":[["U","41,600","65"],["V","41,180","58"],["W","42,480","72"],["X","40,500","50"],["Y","40,400","80"]]}]', '["U","V","W","X","Y"]', 3, '["人口密度＝人口÷面積で求めます。","U：41,600÷65＝640／V：41,180÷58＝710／W：42,480÷72＝590／X：40,500÷50＝810／Y：40,400÷80＝505","最も高いのはXです。","よって、正解は4（X）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増減数の計算', '下の表は、ある町の1年間の出生数と死亡数、町内への転入数と町外への転出数を表したものである。この町の人口は、この1年間で何人変化したか。', '[{"headers":["項目","人数"],"rows":[["出生数","15,230人"],["死亡数","11,480人"],["転入数","72,340人"],["転出数","75,610人"]]}]', '["480人増加","3,750人増加","3,270人減少","7,020人増加"]', 0, '["人口の変化＝（出生数－死亡数）＋（転入数－転出数）で求めます。","出生－死亡：15,230－11,480＝3,750人増加。","転入－転出：72,340－75,610＝－3,270人（3,270人減少）。","合計：3,750－3,270＝480人増加。","コツ：選択肢2・3は、出生死亡・転入転出のどちらか一方だけを計算したひっかけです。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増減数の計算', '下の表は、ある会社の1年間の社員数の変動を表したものである。この会社の社員数は、この1年間で何人変化したか。', '[{"headers":["項目","人数"],"rows":[["入社数","320人"],["退社数","215人"],["他部署からの異動","140人"],["他部署への異動","165人"]]}]', '["80人増加","105人増加","25人減少","130人増加"]', 0, '["社員数の変化＝（入社数－退社数）＋（異動による転入－異動による転出）で求めます。","320－215＝105人増加。140－165＝25人減少。","合計：105－25＝80人増加。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増減数の計算', '下の表は、ある店舗の1か月間の在庫の変動を表したものである。この店舗の在庫数は、この1か月間で何個変化したか。', '[{"headers":["項目","個数"],"rows":[["仕入数","4,850個"],["販売数","4,620個"],["返品受入数","180個"],["廃棄数","95個"]]}]', '["315個増加","230個増加","135個増加","400個増加"]', 0, '["在庫の変化＝（仕入数－販売数）＋（返品受入数－廃棄数）で求めます。","4,850－4,620＝230個増加。180－95＝85個増加。","合計：230＋85＝315個増加。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増減数の計算', '下の表は、あるスポーツジムの1か月間の会員数の変動を表したものである。この会員数は、この1か月間で何人変化したか。', '[{"headers":["項目","人数"],"rows":[["新規入会","268人"],["退会","198人"],["休会からの復帰","54人"],["休会開始","71人"]]}]', '["53人増加","70人増加","17人減少","87人増加"]', 0, '["268－198＝70人増加。54－71＝17人減少。","合計：70－17＝53人増加。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増減数の計算', '下の表は、ある市の年間予算の項目を表したものである（単位：万円）。準備金は、この1年間で何万円変化したか。', '[{"headers":["項目","金額（万円）"],"rows":[["税収入","89,400"],["補助金","34,200"],["人件費","71,600"],["公共事業費","48,900"]]}]', '["3,100万円増加","17,800万円増加","2,900万円増加","6,200万円増加"]', 0, '["収入合計：89,400＋34,200＝123,600万円。支出合計：71,600＋48,900＝120,500万円。","差額：123,600－120,500＝3,100万円増加。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '比率・割合の比較', '下の表は、ある会社の4年間の売上と経費を表したものです。経費率（経費÷売上）が最も低い年はどれですか？', '[{"headers":["年","売上（百万円）","経費（百万円）"],"rows":[["2021","620","186"],["2022","580","158"],["2023","705","197"],["2024","660","172"]]}]', '["2021年","2022年","2023年","2024年"]', 3, '["2021：186÷620＝30.0%／2022：158÷580≈27.2%／2023：197÷705≈27.9%／2024：172÷660≈26.1%","最も低いのは2024年です。","よって、正解は4（2024年）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '比率・割合の比較', '下の表は、ある会社の4店舗の売上目標と実績を表したものです。達成率（実績÷目標）が最も高い店舗はどれですか？', '[{"headers":["店舗","目標（万円）","実績（万円）"],"rows":[["X店","850","782"],["Y店","640","608"],["Z店","920","865"],["W店","730","701"]]}]', '["X店","Y店","Z店","W店"]', 3, '["X：782÷850＝92.0%／Y：608÷640＝95.0%／Z：865÷920≈94.0%／W：701÷730≈96.0%","最も高いのはW店です。","よって、正解は4（W店）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '比率・割合の比較', '下の表は、ある工場の4本の生産ラインの生産数と不良品数を表したものです。不良率（不良品数÷生産数）が最も低いラインはどれですか？', '[{"headers":["ライン","生産数","不良品数"],"rows":[["Aライン","12,400","186"],["Bライン","9,800","137"],["Cライン","15,600","203"],["Dライン","11,200","151"]]}]', '["Aライン","Bライン","Cライン","Dライン"]', 2, '["A：186÷12,400≈1.50%／B：137÷9,800≈1.40%／C：203÷15,600≈1.30%／D：151÷11,200≈1.35%","最も低いのはCラインです。","よって、正解は3（Cライン）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '比率・割合の比較', '下の表は、ある学校の4クラスの在籍者数と出席者数を表したものです。出席率（出席者数÷在籍者数）が最も高いクラスはどれですか？', '[{"headers":["クラス","在籍者数","出席者数"],"rows":[["1組","38","35"],["2組","42","39"],["3組","36","34"],["4組","40","37"]]}]', '["1組","2組","3組","4組"]', 2, '["1組：35÷38≈92.1%／2組：39÷42≈92.9%／3組：34÷36≈94.4%／4組：37÷40＝92.5%","最も高いのは3組です。","よって、正解は3（3組）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '比率・割合の比較', '下の表は、ある選挙区の4人の候補者の投票総数と獲得票数を表したものです。得票率（獲得票数÷投票総数）が最も高い候補者はどれですか？', '[{"headers":["候補者","投票総数","獲得票数"],"rows":[["甲","16,500","7,920"],["乙","13,200","6,468"],["丙","19,800","9,900"],["丁","14,850","7,326"]]}]', '["甲","乙","丙","丁"]', 2, '["甲：7,920÷16,500＝48.0%／乙：6,468÷13,200＝49.0%／丙：9,900÷19,800＝50.0%／丁：7,326÷14,850≈49.3%","最も高いのは丙です。","よって、正解は3（丙）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '平均の計算', '下の表は、ある学校の4クラスの英語テスト結果です。平均点が最も高いクラスはどれですか？', '[{"headers":["クラス","受験者数（人）","合計点"],"rows":[["1組","34","2,822"],["2組","29","2,146"],["3組","37","2,701"],["4組","31","2,356"]]}]', '["1組","2組","3組","4組"]', 0, '["1組：2,822÷34＝83.0点／2組：2,146÷29＝74.0点／3組：2,701÷37＝73.0点／4組：2,356÷31＝76.0点","最も高いのは1組です。","よって、正解は1（1組）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '平均の計算', '下の表は、ある会社の4店舗の来客数と総売上を表したものです。平均客単価（総売上÷来客数）が最も高い店舗はどれですか？', '[{"headers":["店舗","来客数（人）","総売上（円）"],"rows":[["P店","420","1,596,000"],["Q店","380","1,558,000"],["R店","450","1,710,000"],["S店","410","1,517,000"]]}]', '["P店","Q店","R店","S店"]', 1, '["P：1,596,000÷420＝3,800円／Q：1,558,000÷380＝4,100円／R：1,710,000÷450＝3,800円／S：1,517,000÷410＝3,700円","最も高いのはQ店です。","よって、正解は2（Q店）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '平均の計算', '下の表は、ある会社の4部署の人数と平均年齢を表したものです。全社員（4部署合計）の平均年齢は何歳ですか？（小数第1位まで）', '[{"headers":["部署","人数（人）","平均年齢（歳）"],"rows":[["営業部","45","34.0"],["開発部","60","29.5"],["総務部","15","41.0"],["製造部","80","36.0"]]}]', '["34.0歳","35.1歳","32.6歳","33.5歳"]', 0, '["全社員の年齢の合計＝45×34.0＋60×29.5＋15×41.0＋80×36.0＝1,530＋1,770＋615＋2,880＝6,795","全社員数＝45＋60＋15＋80＝200人","平均年齢＝6,795÷200＝33.975≈34.0歳","コツ：単純に4部署の平均年齢（34.0,29.5,41.0,36.0）をそのまま平均してはいけません。人数で重み付けした加重平均が必要です。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '平均の計算', '下の表は、ある会社の4拠点の人数と平均通勤時間を表したものです。全社員（4拠点合計）の平均通勤時間は何分ですか？（小数第1位まで）', '[{"headers":["拠点","人数（人）","平均通勤時間（分）"],"rows":[["本社","120","38"],["支社A","75","52"],["支社B","50","29"],["支社C","95","45"]]}]', '["41.7分","41.0分","43.3分","40.5分"]', 0, '["合計＝120×38＋75×52＋50×29＋95×45＝4,560＋3,900＋1,450＋4,275＝14,185","全人数＝120＋75＋50＋95＝340人","平均＝14,185÷340≈41.7分","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '平均の計算', '下の表は、ある商品の4ロットの数量と総額を表したものです。4ロット全体の平均単価はいくらですか？（円未満四捨五入）', '[{"headers":["ロット","数量（個）","総額（円）"],"rows":[["A","250","875,000"],["B","180","738,000"],["C","320","1,152,000"],["D","150","555,000"]]}]', '["約3,689円","約3,725円","約3,650円","約3,700円"]', 0, '["総額の合計＝875,000＋738,000＋1,152,000＋555,000＝3,320,000円","総数量の合計＝250＋180＋320＋150＝900個","平均単価＝3,320,000÷900≈3,689円","コツ：各ロットの単価（3,500円・4,100円・3,600円・3,700円）を単純平均（3,725円）してはいけません。数量で重み付けが必要です。","よって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増加率・成長率の比較', '下の表は、ある会社の4年間の売上を表したものです。前年比の増加率が最も高い年はどれですか？', '[{"headers":["年","売上（百万円）"],"rows":[["2021","480"],["2022","552"],["2023","607"],["2024","673"]]}]', '["2022年","2023年","2024年"]', 0, '["2022：(552－480)÷480＝15.0%／2023：(607－552)÷552≈10.0%／2024：(673－607)÷607≈10.9%","最も高いのは2022年です。","コツ：売上の絶対額の増加幅（2022年は72、2024年は66）ではなく、増加「率」（元の値に対する割合）で比べる点に注意します。","よって、正解は1（2022年）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増加率・成長率の比較', '下の表は、4つの都市の昨年と今年の人口を表したものです。人口の増加率が最も高い都市はどれですか？', '[{"headers":["都市","昨年人口","今年人口"],"rows":[["甲市","52,000","54,600"],["乙市","38,000","39,900"],["丙市","61,000","63,050"],["丁市","45,000","47,700"]]}]', '["甲市","乙市","丙市","丁市"]', 3, '["甲：(54,600－52,000)÷52,000＝5.0%／乙：(39,900－38,000)÷38,000＝5.0%／丙：(63,050－61,000)÷61,000≈3.4%／丁：(47,700－45,000)÷45,000＝6.0%","最も高いのは丁市です。","よって、正解は4（丁市）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増加率・成長率の比較', '下の表は、4店舗の前月と今月の来客数を表したものです。来客数の減少率が最も大きい店舗はどれですか？', '[{"headers":["店舗","前月来客数","今月来客数"],"rows":[["A店","2,400","2,160"],["B店","1,800","1,584"],["C店","2,650","2,385"],["D店","2,100","1,932"]]}]', '["A店","B店","C店","D店"]', 1, '["A：(2,400－2,160)÷2,400＝10.0%／B：(1,800－1,584)÷1,800＝12.0%／C：(2,650－2,385)÷2,650＝10.0%／D：(2,100－1,932)÷2,100＝8.0%","最も大きいのはB店です。","よって、正解は2（B店）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増加率・成長率の比較', '下の表は、4種類の資材の昨年と今年の単価を表したものです。単価の上昇率が最も高い資材はどれですか？', '[{"headers":["資材","昨年単価（円）","今年単価（円）"],"rows":[["鋼材","820","902"],["木材","540","583"],["樹脂","610","677"],["アルミ","1,150","1,230.5"]]}]', '["鋼材","木材","樹脂","アルミ"]', 2, '["鋼材：(902－820)÷820＝10.0%／木材：(583－540)÷540≈8.0%／樹脂：(677－610)÷610≈11.0%／アルミ：(1,230.5－1,150)÷1,150＝7.0%","最も高いのは樹脂です。","よって、正解は3（樹脂）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '増加率・成長率の比較', '下の表は、4つのアプリの昨年と今年の利用者数を表したものです。利用者数の増加率が最も高いアプリはどれですか？', '[{"headers":["アプリ","昨年利用者数","今年利用者数"],"rows":[["P","125,000","143,750"],["Q","98,000","107,800"],["R","156,000","171,600"],["S","87,000","98,310"]]}]', '["P","Q","R","S"]', 0, '["P：(143,750－125,000)÷125,000＝15.0%／Q：(107,800－98,000)÷98,000＝10.0%／R：(171,600－156,000)÷156,000＝10.0%／S：(98,310－87,000)÷87,000＝13.0%","最も高いのはPです。","よって、正解は1（P）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単価・生産性の比較', '下の表は、4つの工場の従業員数と生産量を表したものです。従業員1人あたりの生産量が最も多い工場はどれですか？', '[{"headers":["工場","従業員数（人）","生産量（個）"],"rows":[["甲工場","80","17,200"],["乙工場","65","13,325"],["丙工場","95","20,900"],["丁工場","72","14,976"]]}]', '["甲工場","乙工場","丙工場","丁工場"]', 2, '["甲：17,200÷80＝215／乙：13,325÷65＝205／丙：20,900÷95＝220／丁：14,976÷72＝208","最も多いのは丙工場です。","よって、正解は3（丙工場）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単価・生産性の比較', '下の表は、4車種の走行距離と消費燃料を表したものです。燃費（走行距離÷消費燃料）が最も良い車種はどれですか？', '[{"headers":["車種","走行距離（km）","消費燃料（L）"],"rows":[["A車","495","33"],["B車","416","26"],["C車","552","40"],["D車","294","21"]]}]', '["A車","B車","C車","D車"]', 1, '["A：495÷33＝15.0km/L／B：416÷26＝16.0km/L／C：552÷40＝13.8km/L／D：294÷21＝14.0km/L","最も良いのはB車です。","よって、正解は2（B車）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単価・生産性の比較', '下の表は、4社の発注個数と発注総額を表したものです。1個あたりの仕入単価が最も安いのはどれですか？', '[{"headers":["仕入先","発注個数","発注総額（円）"],"rows":[["甲社","1,200","462,000"],["乙社","950","378,100"],["丙社","1,450","539,400"],["丁社","800","328,000"]]}]', '["甲社","乙社","丙社","丁社"]', 2, '["甲：462,000÷1,200＝385円／乙：378,100÷950＝398円／丙：539,400÷1,450＝372円／丁：328,000÷800＝410円","最も安いのは丙社です。","よって、正解は3（丙社）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単価・生産性の比較', '下の表は、4人の社員の月間労働時間と月給を表したものです。時給換算（月給÷労働時間）が最も高いのは誰ですか？', '[{"headers":["社員","月間労働時間","月給（円）"],"rows":[["Aさん","160","320,000"],["Bさん","150","315,000"],["Cさん","172","309,600"],["Dさん","145","297,250"]]}]', '["Aさん","Bさん","Cさん","Dさん"]', 1, '["A：320,000÷160＝2,000円／B：315,000÷150＝2,100円／C：309,600÷172＝1,800円／D：297,250÷145＝2,050円","最も高いのはBさんです。","よって、正解は2（Bさん）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '単価・生産性の比較', '下の表は、4つの農場の面積と収穫量を表したものです。面積あたりの収穫量（収穫量÷面積）が最も多い農場はどれですか？', '[{"headers":["農場","面積（a）","収穫量（kg）"],"rows":[["甲農場","45","3,825"],["乙農場","38","3,268"],["丙農場","52","4,368"],["丁農場","60","4,800"]]}]', '["甲農場","乙農場","丙農場","丁農場"]', 1, '["甲：3,825÷45＝85kg/a／乙：3,268÷38＝86kg/a／丙：4,368÷52＝84kg/a／丁：4,800÷60＝80kg/a","最も多いのは乙農場です。","よって、正解は2（乙農場）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '概算による比較', '下の表は、4商品の単価と販売数を表したものです。総売上（単価×販売数）が最も高い商品はどれですか？', '[{"headers":["商品","単価（円）","販売数（個）"],"rows":[["P","1,280","3,400"],["Q","950","4,650"],["R","1,650","2,580"],["S","1,120","3,950"]]}]', '["P","Q","R","S"]', 3, '["P：1,280×3,400＝4,352,000円／Q：950×4,650＝4,417,500円／R：1,650×2,580＝4,257,000円／S：1,120×3,950＝4,424,000円","コツ：QとSはおおまかな概算では差がほとんど見えません（どちらも約440万円）。このように僅差の場合は、概算だけで判断せず必ず正確に計算しましょう。","最も高いのはSです。","よって、正解は4（S）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '概算による比較', '下の表は、4つのプロジェクトの人員数・日数・日当を表したものです。総人件費（人数×日数×日当）が最も低いプロジェクトはどれですか？', '[{"headers":["プロジェクト","人数","日数","日当（円）"],"rows":[["甲","12","25","9,800"],["乙","15","20","9,500"],["丙","10","28","10,200"],["丁","18","18","8,900"]]}]', '["甲","乙","丙","丁"]', 1, '["甲：12×25×9,800＝2,940,000円／乙：15×20×9,500＝2,850,000円／丙：10×28×10,200＝2,856,000円／丁：18×18×8,900＝2,883,600円","乙と丙は僅差（6,000円差）なので正確な計算が必要です。最も低いのは乙です。","よって、正解は2（乙）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '概算による比較', '下の表は、4店舗の客単価・1日あたり客数・営業日数（1か月）を表したものです。月間総売上が最も高い店舗はどれですか？', '[{"headers":["店舗","客単価（円）","1日あたり客数","営業日数"],"rows":[["A店","1,850","120","26"],["B店","2,100","95","28"],["C店","1,650","145","25"],["D店","1,950","110","27"]]}]', '["A店","B店","C店","D店"]', 2, '["A：1,850×120×26＝5,772,000円／B：2,100×95×28＝5,586,000円／C：1,650×145×25＝5,981,250円／D：1,950×110×27＝5,791,500円","最も高いのはC店です。","よって、正解は3（C店）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '概算による比較', '下の表は、4つの町の世帯数と1世帯あたりの平均人数を表したものです。人口（世帯数×1世帯あたり人数）が最も多い町はどれですか？', '[{"headers":["町","世帯数","1世帯あたり平均人数"],"rows":[["あ町","8,200","2.35"],["い町","7,650","2.48"],["う町","9,100","2.18"],["え町","6,900","2.62"]]}]', '["あ町","い町","う町","え町"]', 2, '["あ：8,200×2.35＝19,270人／い：7,650×2.48＝18,972人／う：9,100×2.18＝19,838人／え：6,900×2.62＝18,078人","最も多いのはう町です。","よって、正解は3（う町）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '概算による比較', '下の表は、4つの長方形の圃場の縦・横の長さを表したものです。面積が最も大きい圃場はどれですか？', '[{"headers":["圃場","縦（m）","横（m）"],"rows":[["A","186","240"],["B","210","215"],["C","165","275"],["D","198","228"]]}]', '["A","B","C","D"]', 2, '["A：186×240＝44,640㎡／B：210×215＝45,150㎡／C：165×275＝45,375㎡／D：198×228＝45,144㎡","B・D・Cは僅差なので、正確な計算が必要です。最も大きいのはCです。","よって、正解は3（C）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '複合読み取り問題', '下の表は、4店舗の売上と利益を表したものです。利益率（利益÷売上）が2番目に高い店舗はどれですか？', '[{"headers":["店舗","売上（万円）","利益（万円）"],"rows":[["W店","2,400","312"],["X店","1,800","270"],["Y店","3,100","341"],["Z店","2,650","371"]]}]', '["W店","X店","Y店","Z店"]', 3, '["利益率：W＝312÷2,400＝13.0%／X＝270÷1,800＝15.0%／Y＝341÷3,100＝11.0%／Z＝371÷2,650＝14.0%","利益率の高い順は、X(15.0%)＞Z(14.0%)＞W(13.0%)＞Y(11.0%)です。","コツ：利益の「金額」で見るとZ店（371万円）が最大ですが、利益「率」で見るとZ店は2番目にすぎません。金額と率を混同しないよう注意しましょう。","よって、正解は4（Z店）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '複合読み取り問題', '下の表は、4つの地域の面積・人口密度・予算総額を表したものです。住民1人あたりの予算額が最も多い地域はどれですか？', '[{"headers":["地域","面積（km²）","人口密度（人/km²）","予算総額（百万円）"],"rows":[["甲","42","650","910"],["乙","55","520","980"],["丙","38","730","890"],["丁","60","490","960"]]}]', '["甲","乙","丙","丁"]', 1, '["まず人口＝面積×人口密度を求めます。","甲：42×650＝27,300人／乙：55×520＝28,600人／丙：38×730＝27,740人／丁：60×490＝29,400人","次に、1人あたり予算＝予算総額÷人口を求めます（百万円÷人）。","甲：910÷27,300≈0.0333百万円（約33,333円）／乙：980÷28,600≈0.0343百万円（約34,266円）／丙：890÷27,740≈0.0321百万円（約32,085円）／丁：960÷29,400≈0.0327百万円（約32,653円）","最も多いのは乙です。","よって、正解は2（乙）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '複合読み取り問題', '下の表は、4クラスの平均点と合計点を表したものです（受験者数は表に記載されていません）。受験者数が最も多いクラスはどれですか？', '[{"headers":["クラス","平均点","合計点"],"rows":[["1組","76.0","2,660"],["2組","81.5","2,771"],["3組","74.5","2,831"],["4組","79.0","2,449"]]}]', '["1組","2組","3組","4組"]', 2, '["受験者数＝合計点÷平均点で逆算します。","1組：2,660÷76.0＝35人／2組：2,771÷81.5＝34人／3組：2,831÷74.5＝38人／4組：2,449÷79.0＝31人","最も多いのは3組です。","よって、正解は3（3組）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '複合読み取り問題', '下の表は、4部門の昨年実績と今年の成長率を表したものです。今年の実績（昨年実績×(1＋成長率)）が最も大きい部門はどれですか？', '[{"headers":["部門","昨年実績（百万円）","成長率"],"rows":[["営業","420","＋12%"],["開発","380","＋18%"],["製造","510","＋5%"],["管理","290","＋22%"]]}]', '["営業部門","開発部門","製造部門","管理部門"]', 2, '["営業：420×1.12＝470.4／開発：380×1.18＝448.4／製造：510×1.05＝535.5／管理：290×1.22＝353.8","コツ：成長率だけを見て「管理部門（＋22%）が一番伸びている」と即断してはいけません。もとの実績の大きさも掛け合わせて比較する必要があります。","最も大きいのは製造部門です。","よって、正解は3（製造部門）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_new_math', '図表の読み取り', '複合読み取り問題', '下の表は、4人のゴルフ選手の合計打数とラウンド数を表したものです。平均ストローク（1ラウンドあたりの打数）が最も少ない（良い）選手は誰ですか？', '[{"headers":["選手","合計打数","ラウンド数"],"rows":[["選手A","288","4"],["選手B","213","3"],["選手C","352","5"],["選手D","141","2"]]}]', '["選手A","選手B","選手C","選手D"]', 2, '["A：288÷4＝72.0／B：213÷3＝71.0／C：352÷5＝70.4／D：141÷2＝70.5","コツ：合計打数が最も少ないのはD（141）ですが、これはラウンド数も少ないためです。1ラウンドあたりで比べる必要があります。","最も少ないのは選手Cです。","よって、正解は3（選手C）・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型非言語: 図表の読み取り）');
